package com.fream.back.domain.shipment.entity;

import com.fream.back.domain.product.entity.Product;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Table(name = "address",
        indexes = {
                @Index(name = "idx_user_id", columnList = "user_id"),
                @Index(name = "idx_is_default", columnList = "is_default")
        }
)
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Shipment extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Product user;

    @Column(nullable = false)
    private String recipientName;

    @Column(nullable = false)
    private String phoneNumber;

    @Column(nullable = false)
    private String zipCode;

    @Column(nullable = false)
    private String address;

    private String detailedAddress;

    @Column(name = "is_default")
    private boolean isDefault;


    public void updateAddress(String recipientName, String phoneNumber, String zipCode,
                              String address, String detailedAddress, Boolean isDefault) {
        if (recipientName != null) {
            this.recipientName = recipientName;
        }
        if (phoneNumber != null) {
            this.phoneNumber = phoneNumber;
        }
        if (zipCode != null) {
            this.zipCode = zipCode;
        }
        if (address != null) {
            this.address = address;
        }
        if (detailedAddress != null) {
            this.detailedAddress = detailedAddress;
        }
        if (isDefault != null) {
            this.isDefault = isDefault;
        }
    }


    public void assignUser(Product user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }
}package com.fream.back.domain.shipment.service.command;

import com.fream.back.domain.shipment.dto.ShipmentCreateDto;
import com.fream.back.domain.shipment.dto.ShipmentUpdateDto;
import com.fream.back.domain.shipment.entity.Shipment;
import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
import com.fream.back.domain.shipment.exception.ShipmentException;
import com.fream.back.domain.shipment.exception.ShipmentNotFoundException;
import com.fream.back.domain.shipment.exception.ShipmentProductNotFoundException;
import com.fream.back.domain.shipment.repository.ShipmentRepository;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.repository.ProductRepository;
import com.fream.back.global.utils.PersonalDataEncryptionUtil;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class ShipmentCommandService {

    private final ProductRepository userRepository;
    private final ShipmentRepository addressRepository;
    private final PersonalDataEncryptionUtil encryptionUtil;


    @Transactional
    public void createAddress(String email, ShipmentCreateDto createDto) {
        try {
            Product user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 생성 시작: 사용자={}, 수신자={}", email, createDto.getRecipientName());

            if (createDto.getIsDefault() != null && createDto.getIsDefault()) {

                log.debug("기존 기본 주소 해제: 사용자={}", email);
                user.getAddresses().forEach(address -> address.updateAddress(
                        null, null, null, null, null, false));
            }



            String encryptedRecipientName = encryptionUtil.deterministicEncrypt(createDto.getRecipientName());
            String encryptedPhoneNumber = encryptionUtil.deterministicEncrypt(createDto.getPhoneNumber());
            String encryptedZipCode = encryptionUtil.deterministicEncrypt(createDto.getZipCode());
            String encryptedAddress = encryptionUtil.deterministicEncrypt(createDto.getAddress());


            String encryptedDetailedAddress = createDto.getDetailedAddress() != null ?
                    encryptionUtil.encrypt(createDto.getDetailedAddress()) : null;

            Shipment newAddress = Shipment.builder()
                    .user(user)
                    .recipientName(encryptedRecipientName)
                    .phoneNumber(encryptedPhoneNumber)
                    .zipCode(encryptedZipCode)
                    .address(encryptedAddress)
                    .detailedAddress(encryptedDetailedAddress)
                    .isDefault(createDto.getIsDefault() != null && createDto.getIsDefault())
                    .build();

            addressRepository.save(newAddress);
            log.info("주소 생성 완료: 사용자={}, 주소ID={}", email, newAddress.getId());
